 if(job){phase=task?(task.progressStage||({ready:'queued',cooldown:'cooldown',queued:'queued',running:'reading',publishing:'archiving','awaiting-confirmation':'archiving'}[task.status])||'reading'):{'cooldown-search':'cooldown','cooldown-next':'cooldown',ready:'queued',searching:'searching','reading-candidate':'reading','waiting-next':'next','agent-next-dispatched':'next','agent-start-dispatched':'queued','making-card':'reading'}[job.stage]||'queued';}
 else if(task)phase=task.progressStage||({ready:'queued',cooldown:'cooldown',queued:'queued',running:'reading',publishing:'archiving','awaiting-confirmation':'archiving'}[task.status])||'reading';
 else {const latestTask=tasks[0],latestJob=jobs.find(row=>row.kind==='jd-auto-card-batch'),latest=latestJob&&(!latestTask||latestTask.batchId===latestJob.id||Date.parse(latestJob.createdAt)>=Date.parse(latestTask.createdAt))?latestJob:latestTask;if(latest){phase=latest.status==='completed'?(latest.dataQuality?.level==='partial'||latest.kind==='jd-auto-card-batch'&&tasks.some(row=>row.batchId===latest.id&&row.dataQuality?.level==='partial')?'partial':'completed'):'stopped';done=latest.kind==='jd-auto-card-batch'?(latest.completed||0):(latest.status==='completed'?1:0);total=latest.settings?.quantity||1;}}
 if((job||task)&&['checking','opening','waiting'].includes(connection.phase))phase='connecting';
