function productTaskPrompt(task){return AUTOMATION_CONTRACT+CAPTURE_DELIVERY_CONTRACT+productTimingContract(task)+(task.localSourceTaskId?'本次从已校验的本地详情存档继续制卡，不重新访问商品页或图片服务器；价格与参数沿用原采集时间，不能声称刚刚重新读取。':'')+'执行用户点击的全自动商品规格卡任务。只处理 '+task.sourceUrl+'，任务ID '+task.id+'。本次只调用sofa_monitor_product_task，参数'+JSON.stringify({id:task.id,action:'run'})+'。run在后台依次完成官方参数读取、详情原图本地存档、DeepSeek V4.1 Flash图片核对、具体卖点提取、45度主图选择/编辑、完整部件细节选图、1920×1080排版和自动归档；不要另开网页或自行拆步骤。browserCheckpoint只是阶段资料，不是规格卡；工具错误必须按errorCode与readDiagnostics.toolFailure简报，不能将无返回内容误判为无商品资料。详情模型或商品处理失败时后台会诊断桌面工具是否能补救；最多2轮、累计10分钟且计入单个商品30分钟，随后用已收集资料出卡。未核对的图片不能声称已核对。不自行拆成start/finish，不手写manifest，不让用户选择图片或尺寸口径。若返回replayed或completed，直接报告既有结果；失败也按返回状态简报，后台自行跳过或停止，不询问用户恢复方案。属于批次时插件自动安排下一条，不自行调用next。若dataQuality.level为partial，必须明确说资料未齐全并列出dataQuality.missing，不得仅回复采集成功。dataConflicts非空时同时报告参数表与已选款式两种原文，不擅自消除矛盾。若warnings非空须简报缺项；readDiagnostics说明实际读取，不把缺图或缺参数宣称为完整成功。不提出任何后续选择题，只返回实际状态、文件、本地详情存档和来源。detailReview记录实际模型、提交图片数量及覆盖情况；revision1017Verified不是true时不能声称已核实1017版本。';}
function batchTaskPrompt(job,action){return AUTOMATION_CONTRACT+CAPTURE_DELIVERY_CONTRACT+BATCH_TIMING_CONTRACT+'执行沙发爬取的自动制卡批次 '+job.id+'。本次动作 '+action+'。本次只调用sofa_monitor_card_batch，参数'+JSON.stringify({id:job.id,action})+'，然后简短返回。调度器会自动推进整个批次、处理单品和安排下一条。不要把一次分步返回当成整批结束，不向用户咨询后续方案，不询问是否继续。普通缺项由执行器保留未取得，补救耗尽也用已有资料出不完整卡，不能凑满时按返回结果报告实际数量，不重建批次。partial表示已归档但资料未齐全的卡片数，必须如实报告，不能将其称为完整规格卡。每条结束后至少等待 '+(job.settings.intervalMinutes||5)+' 分钟；等待期间不访问平台。参数 '+JSON.stringify(job.settings)+'。只有登录验证、权限拒绝或实际工具不可用才报告阻断，不提出确认问题。';}


// Collection occupancy is separate from the native browser's connection state.
// Waiting batches still own the workflow; never interrupt or start a second run.
function currentCaptureBlocker(state){
  const batch=state?.jobs?.find(row=>row.kind==='jd-auto-card-batch'&&['ready','running'].includes(row.status));
  if(batch)return '批量采集正在执行；单次采集请先点右侧“停止本次采集”。';
  if(state?.jobs?.some(row=>row.status==='running'))return '已有采集任务正在执行，请先停止或等待完成。';
  if(state?.productTasks?.some(row=>['ready','queued','running','cooldown','publishing'].includes(row.status)))return '正在处理商品，请等待本次采集完成。';
  return '';
}

